trace=Path(sys.argv[1]).read_text(encoding='ascii',errors='replace').splitlines();checks={'trace_exact':trace==expected,'two_user_domains_protected':('GP_COUNT=02' in trace),'good_ignores_untrusted_claim':all(x in trace for x in ['GOOD_CLAIM=01','GOOD_ACTUAL=02','GOOD_FORGED_WRITE=U','GOOD_AFTER=7E']),'valid_a_future_survives_good_denial':all(x in trace for x in ['A_READ_AFTER=W','A_VAL_AFTER=7E']),'bad_claim_trust_loses_protection':all(x in trace for x in ['BAD_CLAIM=01','BAD_ACTUAL=02','BAD_FORGED_WRITE=W','BAD_AFTER=55'])};out={'format':'C004_P20_EVALUATION_V1','passed':all(checks.values()),'checks':checks,'trace':trace};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8',newline='\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
